      $UsedSpace = $($configuration[$count + 3]).Trim()
      $UsedSpace = $UsedSpace.Substring($UsedSpace.IndexOf(':') + 2)

      $AllocatedSpace = $($configuration[$count + 4]).Trim()
      $AllocatedSpace = $AllocatedSpace.Substring($AllocatedSpace.IndexOf(':') + 2)

